package cn.aiworkspace.personal;
import android.content.*;
import android.database.*;
import android.database.sqlite.*;
import org.json.*;

final class Store extends SQLiteOpenHelper {
 final SQLiteDatabase db;
 Store(Context c){super(c,"ai-workspace.sqlite",null,1);setWriteAheadLoggingEnabled(true);db=getWritableDatabase();db.execSQL("PRAGMA synchronous=FULL");if(project("inbox")==null)saveProject(J.obj("id","inbox","name","随手聊","instructions",""));recover();}
 @Override public void onConfigure(SQLiteDatabase d){d.setForeignKeyConstraintsEnabled(true);}
 @Override public void onCreate(SQLiteDatabase d){for(String sql:Schema.SQL)d.execSQL(sql);}
 @Override public void onUpgrade(SQLiteDatabase d,int old,int next){throw new IllegalStateException("数据库版本不受支持，请先导出备份");}
 private JSONObject parse(String s){try{return new JSONObject(s);}catch(Exception e){throw new IllegalStateException("本机数据读取失败，未覆盖原数据",e);}}
 private void put(String table,ContentValues v){db.insertWithOnConflict(table,null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 private ContentValues values(Object... pairs){ContentValues v=new ContentValues();for(int i=0;i<pairs.length;i+=2){String k=(String)pairs[i];Object x=pairs[i+1];if(x instanceof Integer)v.put(k,(Integer)x);else if(x instanceof Long)v.put(k,(Long)x);else v.put(k,x==null?"":x.toString());}return v;}
 synchronized JSONObject data(String table,String id){try(Cursor c=db.rawQuery("SELECT data FROM "+table+" WHERE id=?",new String[]{id})){return c.moveToFirst()?parse(c.getString(0)):null;}}
 synchronized JSONArray records(String table,String where,String[] args,String order){JSONArray a=new JSONArray();try(Cursor c=db.rawQuery("SELECT data FROM "+table+(where.isEmpty()?"":" WHERE "+where)+" ORDER BY "+order,args)){while(c.moveToNext())a.put(parse(c.getString(0)));}return a;}
 synchronized JSONObject project(String id){return data("projects",id);}
 synchronized JSONObject chat(String id){return data("chats",id);}
 synchronized JSONObject provider(String id){return data("providers",id);}
 synchronized JSONArray projects(){return records("projects","archived=0",null,"updated DESC");}
 synchronized JSONArray providers(){return records("providers","",null,"updated DESC");}
 synchronized JSONArray chats(String project){return records("chats","project_id=? AND archived=0",new String[]{project},"updated DESC");}
 synchronized JSONArray messages(String chat){JSONArray a=new JSONArray();try(Cursor c=db.rawQuery("SELECT id,role,body,state,data,created FROM messages WHERE chat_id=? ORDER BY created,rowid",new String[]{chat})){while(c.moveToNext())a.put(J.obj("id",c.getString(0),"role",c.getString(1),"body",c.getString(2),"state",c.getString(3),"meta",parse(c.getString(4)),"created",c.getLong(5)));}return a;}
 synchronized JSONObject lastMessage(String chat){try(Cursor c=db.rawQuery("SELECT id,role,body,state,data,created FROM messages WHERE chat_id=? ORDER BY created DESC,rowid DESC LIMIT 1",new String[]{chat})){return c.moveToFirst()?J.obj("id",c.getString(0),"role",c.getString(1),"body",c.getString(2),"state",c.getString(3),"meta",parse(c.getString(4)),"created",c.getLong(5)):null;}}
 synchronized JSONArray files(String project){JSONArray a=new JSONArray();try(Cursor c=db.rawQuery("SELECT id,name,body,created FROM files WHERE project_id=? ORDER BY created,rowid",new String[]{project})){while(c.moveToNext())a.put(J.obj("id",c.getString(0),"name",c.getString(1),"body",c.getString(2),"created",c.getLong(3)));}return a;}
 synchronized void saveProject(JSONObject x){J.require(!J.str(x,"name").trim().isEmpty(),"请填写项目名称");J.require(J.str(x,"instructions").length()<=40000,"项目说明最多40000字符");if(J.str(x,"id").isEmpty())try{x.put("id",J.id());}catch(Exception ignored){}long now=System.currentTimeMillis();put("projects",values("id",J.str(x,"id"),"name",J.str(x,"name"),"data",x.toString(),"archived",x.optBoolean("archived")?1:0,"updated",now));}
 synchronized void saveProvider(JSONObject x){put("providers",values("id",J.str(x,"id"),"data",x.toString(),"updated",System.currentTimeMillis()));}
 synchronized void saveChat(JSONObject x){put("chats",values("id",J.str(x,"id"),"project_id",J.str(x,"projectId"),"title",J.str(x,"title"),"data",x.toString(),"archived",x.optBoolean("archived")?1:0,"updated",System.currentTimeMillis()));}
 synchronized JSONObject newChat(String project,String provider,String model){J.require(project(project)!=null,"项目不存在");JSONObject c=J.obj("id",J.id(),"projectId",project,"title","新对话","providerId",provider,"model",model,"draft","");saveChat(c);return c;}
 synchronized void draft(String chat,String value){JSONObject x=chat(chat);if(x==null||J.str(x,"draft").equals(value))return;try{x.put("draft",value);saveChat(x);}catch(Exception e){throw new IllegalStateException(e);}}
 synchronized void addFile(String project,String name,String body){J.require(body.length()>0&&body.length()<=800000,"参考文件需为1—800000字符的TXT或Markdown");J.require(project(project)!=null,"项目不存在");db.insertOrThrow("files",null,values("id",J.id(),"project_id",project,"name",name,"body",body,"created",System.currentTimeMillis()));}
 synchronized void removeFile(String id){db.delete("files","id=?",new String[]{id});}
 synchronized JSONObject active(){try(Cursor c=db.rawQuery("SELECT id FROM requests WHERE status IN ('queued','sending') LIMIT 1",null)){return c.moveToFirst()?request(c.getString(0)):null;}}
 synchronized JSONObject request(String id){try(Cursor c=db.rawQuery("SELECT chat_id,assistant_id,status,data,created FROM requests WHERE id=?",new String[]{id})){return c.moveToFirst()?J.obj("id",id,"chatId",c.getString(0),"assistantId",c.getString(1),"status",c.getString(2),"data",parse(c.getString(3)),"created",c.getLong(4)):null;}}
 synchronized JSONObject reserve(String chatId,String text)throws Exception{
  db.beginTransaction();try{J.require(active()==null,"另一条回答仍在生成，可查看其他对话或先停止生成");JSONObject c=chat(chatId);J.require(c!=null,"对话不存在");JSONObject p=provider(J.str(c,"providerId"));J.require(p!=null,"先添加 API 服务商并选择模型");J.require(!J.str(p,"keyCipher").isEmpty(),"请先在API设置填写密钥");J.require(!text.trim().isEmpty(),"请输入消息");p=ApiProtocol.validate(p);String model=J.str(c,"model");JSONArray history=Conversation.history(messages(chatId));history.put(J.obj("role","user","content",text));String instructions=Conversation.instructions(project(J.str(c,"projectId")),files(J.str(c,"projectId")));JSONObject payload=ApiProtocol.payload(p,model,instructions,history);
   String user=J.id(),assistant=J.id(),id=J.id();long now=System.currentTimeMillis();String label=J.str(p,"name");db.insertOrThrow("messages",null,values("id",user,"chat_id",chatId,"role","user","body",text,"state","done","data","{}","created",now));db.insertOrThrow("messages",null,values("id",assistant,"chat_id",chatId,"role","assistant","body","","state","queued","data",J.obj("provider",label,"model",model,"requestId",id).toString(),"created",now+1));JSONObject d=J.obj("provider",p,"model",model,"payload",payload,"endpoint",ApiProtocol.endpoint(p,model,false),"requestIntentAt",JSONObject.NULL,"userMessageId",user);db.insertOrThrow("requests",null,values("id",id,"chat_id",chatId,"assistant_id",assistant,"status","queued","data",d.toString(),"created",now));if(J.str(c,"title").equals("新对话"))c.put("title",text.replace('\n',' ').substring(0,Math.min(28,text.length())));c.put("draft","");saveChat(c);db.setTransactionSuccessful();return request(id);
  }finally{db.endTransaction();}
 }
 synchronized boolean begin(String id)throws Exception{db.beginTransaction();try{JSONObject r=request(id);if(r==null||!r.optString("status").equals("queued"))return false;JSONObject d=r.getJSONObject("data");d.put("requestIntentAt",System.currentTimeMillis());db.update("requests",values("status","sending","data",d.toString()),"id=? AND status='queued'",new String[]{id});db.update("messages",values("state","streaming"),"id=?",new String[]{r.getString("assistantId")});db.setTransactionSuccessful();return true;}finally{db.endTransaction();}}
 synchronized void partial(String id,ApiProtocol.Output output){JSONObject r=request(id);if(r==null||!r.optString("status").equals("sending"))return;db.update("messages",values("body",output.text.toString()),"id=?",new String[]{J.str(r,"assistantId")});}
 synchronized void finish(String id,String state,ApiProtocol.Output out,String error){if(out!=null)out=out.snapshot();db.beginTransaction();try{JSONObject r=request(id);if(r==null||!r.optString("status").matches("queued|sending"))return;JSONObject d=r.getJSONObject("data"),meta=J.obj("provider",d.getJSONObject("provider").optString("name"),"model",d.optString("model"),"requestId",id,"error",error,"usage",out==null?new JSONObject():out.usage,"finishReason",out==null?"":out.finish,"responseId",out==null?"":out.responseId);d.put("finishedAt",System.currentTimeMillis());d.put("error",error);d.put("usage",out==null?new JSONObject():out.usage);d.put("finishReason",out==null?"":out.finish);d.put("responseId",out==null?"":out.responseId);ContentValues m=values("state",state,"data",meta.toString());if(out!=null)m.put("body",out.text.toString());db.update("messages",m,"id=?",new String[]{r.getString("assistantId")});db.update("requests",values("status",state,"data",d.toString()),"id=?",new String[]{id});db.setTransactionSuccessful();}catch(Exception e){throw new IllegalStateException(e);}finally{db.endTransaction();}}
 private synchronized void recover(){JSONArray ids=new JSONArray();try(Cursor c=db.rawQuery("SELECT id FROM requests WHERE status IN ('queued','sending')",null)){while(c.moveToNext())ids.put(c.getString(0));}for(int i=0;i<ids.length();i++)finish(ids.optString(i),"interrupted",null,"上次进程已结束，部分内容保留；未自动重发。可复制原问题后手动发送。");}
 synchronized void stop(String id){finish(id,"stopped",null,"已停止等待。已被服务商接收的请求仍可能执行或计费。");}
 synchronized JSONObject backup()throws Exception{JSONObject data=new JSONObject();for(String table:new String[]{"projects","providers","chats","messages","files","requests"}){JSONArray rows=new JSONArray();try(Cursor c=db.rawQuery("SELECT * FROM "+table+" ORDER BY rowid",null)){String[] names=c.getColumnNames();while(c.moveToNext()){JSONObject row=new JSONObject();for(int i=0;i<names.length;i++){if(c.getType(i)==Cursor.FIELD_TYPE_INTEGER)row.put(names[i],c.getLong(i));else if(names[i].equals("data"))row.put(names[i],J.noSecrets(parse(c.getString(i))).toString());else row.put(names[i],c.getString(i));}rows.put(row);}}data.put(table,rows);}return J.obj("format","ai-workspace-backup","version",1,"createdAt",System.currentTimeMillis(),"credentialsIncluded",false,"data",data);}
 synchronized int restore(JSONObject backup)throws Exception{J.require(backup.optString("format").equals("ai-workspace-backup")&&backup.optInt("version")==1,"不是AI工作台备份");J.require(active()==null,"请先停止生成再导入");JSONObject source=backup.getJSONObject("data");db.beginTransaction();int count=0;try{for(String table:new String[]{"projects","providers","chats","messages","files","requests"}){JSONArray rows=source.getJSONArray(table);J.require(rows.length()<=100000,"备份记录过多");for(int i=0;i<rows.length();i++){JSONObject row=J.copy(rows.getJSONObject(i));String id=row.getString("id");J.require(id.length()>0&&id.length()<=200,"备份ID无效");try(Cursor existing=db.rawQuery("SELECT id FROM "+table+" WHERE id=?",new String[]{id})){if(existing.moveToFirst())continue;}if(row.has("data")){JSONObject d=J.noSecrets(new JSONObject(row.getString("data")));row.put("data",d.toString());}if(table.equals("requests")&&row.optString("status").matches("queued|sending"))row.put("status","interrupted");if(table.equals("messages")&&row.optString("state").matches("queued|streaming"))row.put("state","interrupted");ContentValues cv=new ContentValues();try(Cursor schema=db.rawQuery("PRAGMA table_info("+table+")",null)){while(schema.moveToNext()){String name=schema.getString(schema.getColumnIndexOrThrow("name"));J.require(row.has(name),"备份缺少字段 "+name);if(schema.getString(schema.getColumnIndexOrThrow("type")).equals("INTEGER"))cv.put(name,row.getLong(name));else cv.put(name,row.getString(name));}}db.insertOrThrow(table,null,cv);count++;}}db.setTransactionSuccessful();return count;}finally{db.endTransaction();}}
}
